public int hourglassSum(int[][] arr) {
    int best = Integer.MIN_VALUE;
    for (int r = 0; r <= 3; r++) {
        for (int c = 0; c <= 3; c++) {
            int top = arr[r][c] + arr[r][c + 1] + arr[r][c + 2];
            int mid = arr[r + 1][c + 1];
            int bottom = arr[r + 2][c] + arr[r + 2][c + 1] + arr[r + 2][c + 2];
            best = Math.max(best, top + mid + bottom);
        }
    }
    return best;
}

