def hourglass_sum(arr: list[list[int]]) -> int:
    rows, cols = len(arr), len(arr[0])
    best = float('-inf')
    for r in range(rows - 2):
        for c in range(cols - 2):
            s = (arr[r][c] + arr[r][c + 1] + arr[r][c + 2]
                 + arr[r + 1][c + 1]
                 + arr[r + 2][c] + arr[r + 2][c + 1] + arr[r + 2][c + 2])
            best = max(best, s)
    return int(best)

